import { atom } from "nanostores";
import { SprinculCore } from "./SprinculCore";
import SprinculModel from "./SprinculModel";
import type {
	BoundDefaults,
	SprinculInitOptions,
	SprinculModelConstructor,
	SprinculModelInfo,
	SprinculModelRegistry,
	SprinculMountOptions,
	SprinculOptions,
} from "./types";
import {
	abortSignal,
	addModelTag,
	closestModelRoot,
	deleteCore,
	deleteInstance,
	getCore,
	getInstance,
	setCore,
	setInstance,
} from "./registry";

/**
 * @class Sprincul
 * @description Static registry and factory. Manages model registration, initialization, and lifecycle.
 */
export default class Sprincul {
	static #registry: SprinculModelRegistry = new Map();
	static #isBrowser = typeof window !== "undefined" && typeof document !== "undefined";
	static #globalStores = new Map<string, ReturnType<typeof atom>>();
	static #processedElements = new WeakSet<HTMLElement>();
	static #instancesByName = new Map<string, Set<SprinculModel>>();
	static #modelNames = new WeakMap<SprinculModel, string>();
	/** Instances mid-teardown: guards against a re-entrant destroy() invoking beforeDestroy twice. */
	static #destroying = new WeakSet<SprinculModel>();
	/** Teardowns waiting on an async beforeDestroy, so a repeat call can wait for the same one. */
	static #teardowns = new WeakMap<SprinculModel, Promise<void>>();
	/** Deprecated call forms already warned about, so each warns once. */
	static #deprecationsWarned = new Set<string>();
	/** Instances with a still-pending async beforeInit. */
	static #pendingBeforeInit = new WeakSet<SprinculModel>();
	/** Tag name -> the name of the model a custom element was defined for. */
	static #customElements = new Map<string, string>();
	/** Connected custom elements waiting to mount, flushed together so nested ones mount first. */
	static #pendingElements = new Set<HTMLElement>();
	static #flushScheduled = false;
	/** Disconnected custom elements, unmounted together in one microtask if they're still off the page. */
	static #disconnectedElements = new Set<HTMLElement>();
	static #unmountScheduled = false;
	/** Custom elements whose unmount is still settling, so reconnecting waits for it. */
	static #elementTeardowns = new WeakMap<HTMLElement, Promise<void>>();
	/** Page-wide defaults from setOption(), below a call's options and a model's `static options`. */
	static #options: SprinculOptions = { devMode: false };

	static store = {
		get<T = any>(key: string): T | undefined {
			const store = Sprincul.#globalStores.get(key);
			return store ? (store.get() as T) : undefined;
		},
		set<T = any>(key: string, value: T): void {
			if (!Sprincul.#globalStores.has(key)) {
				Sprincul.#globalStores.set(key, atom<T>(value));
			}
			Sprincul.#globalStores.get(key)!.set(value);
		},
		/**
		 * Listen for changes to a key. Pass `options.signal` (e.g. a model's `$signal`) to unsubscribe when it aborts.
		 */
		subscribe<T = any>(
			key: string,
			callback: (value: T | undefined) => void,
			options?: { signal?: AbortSignal },
		): () => void {
			if (!Sprincul.#globalStores.has(key)) {
				// Initialize an atom that can hold undefined until a value is set
				Sprincul.#globalStores.set(key, atom<T | undefined>());
			}
			const unsubscribe = Sprincul.#globalStores.get(key)!.listen(callback as (value: any) => void);

			/*
			 * Detach from the signal too, so subscribing and unsubscribing repeatedly doesn't pile up on it.
			 * Runs once: nanostores unbinds by callback, so a second call could drop another subscription sharing it.
			 */
			const signal = options?.signal;
			let stopped = false;
			const stop = () => {
				if (stopped) return;
				stopped = true;
				signal?.removeEventListener("abort", stop);
				unsubscribe();
			};

			if (signal?.aborted) {
				stop();
			} else {
				signal?.addEventListener("abort", stop, { once: true });
			}

			return stop;
		},
		clear(): void {
			Sprincul.#globalStores.clear();
		},
	};

	/**
	 * Set a page-wide default for an option. A model's `static options` and the options passed to
	 * `init()`/`mount()` still override it. Call it before registering or mounting models.
	 */
	static setOption<K extends keyof SprinculOptions>(name: K, value: SprinculOptions[K]): void {
		if (!Object.prototype.hasOwnProperty.call(Sprincul.#options, name)) {
			console.warn(`[Sprincul] setOption() was given an unknown option "${String(name)}".`);
			return;
		}
		Sprincul.#options[name] = value;
	}

	/** Resolves an option: the call's value, then the model's `static options`, then setOption()'s default. */
	static #option<K extends keyof SprinculOptions>(
		name: K,
		modelClass: SprinculModelConstructor | undefined,
		callValue?: SprinculOptions[K],
	): SprinculOptions[K] {
		return callValue ?? modelClass?.options?.[name] ?? Sprincul.#options[name];
	}

	/**
	 * Register a single model class
	 */
	static register(name: string, modelClass: SprinculModelConstructor) {
		Sprincul.#registry.set(name, modelClass);
		Sprincul.#defineCustomElement(name, modelClass);
	}

	/**
	 * Register multiple model classes at once, each under its key. Takes an object literal or a module namespace
	 * (`import * as models`) whose exports are all models; any value that isn't one is skipped with a warning.
	 */
	static registerAll<T extends { [K in keyof T]: SprinculModelConstructor }>(models: T) {
		for (const [name, cls] of Object.entries(models) as [string, unknown][]) {
			if (typeof cls !== "function" || !(cls.prototype instanceof SprinculModel)) {
				console.warn(`[Sprincul] registerAll() skipped "${name}": it isn't a SprinculModel class.`);
				continue;
			}
			Sprincul.#registry.set(name, cls as SprinculModelConstructor);
			Sprincul.#defineCustomElement(name, cls as SprinculModelConstructor);
		}
	}

	/** Defines the custom element a model opts into with `static options = { customElement }`. */
	static #defineCustomElement(modelName: string, modelClass: SprinculModelConstructor): void {
		const name = modelClass.options?.customElement;
		if (!name || typeof customElements === "undefined") return;

		if (customElements.get(name)) {
			if (Sprincul.#customElements.get(name) !== modelName) {
				console.warn(`[Sprincul] <${name}> is already defined, so "${modelName}" can't use it.`);
			}
			return;
		}

		class SprinculElement extends HTMLElement {
			/** The mounted model, for debugging. Like onReady payloads, only devMode hands it out. */
			get model(): SprinculModel | undefined {
				return Sprincul.#option("devMode", modelClass) ? getInstance(this) : undefined;
			}

			connectedCallback() {
				Sprincul.#queueMount(this);
			}

			disconnectedCallback() {
				Sprincul.#queueUnmount(this);
			}
		}

		try {
			customElements.define(name, SprinculElement);
		} catch (e) {
			console.warn(`[Sprincul] Couldn't define <${name}> for "${modelName}":`, e);
			return;
		}
		Sprincul.#customElements.set(name, modelName);
		addModelTag(name);
	}

	static #isCustomElement(element: Element): boolean {
		return Sprincul.#customElements.has(element.localName);
	}

	static #queueMount(element: HTMLElement): void {
		Sprincul.#pendingElements.add(element);
		if (Sprincul.#flushScheduled) return;
		Sprincul.#flushScheduled = true;

		const flush = () => {
			Sprincul.#flushScheduled = false;
			Sprincul.#takePendingElements(document)
				.sort(Sprincul.#childrenFirst)
				.forEach((element) => Sprincul.#mountCustomElement(element));
		};

		// Defined before the parser reached them, they connect before their children exist
		if (document.readyState === "loading") {
			document.addEventListener("DOMContentLoaded", flush, { once: true });
		} else {
			queueMicrotask(flush);
		}
	}

	static #queueUnmount(element: HTMLElement): void {
		Sprincul.#disconnectedElements.add(element);
		if (Sprincul.#unmountScheduled) return;
		Sprincul.#unmountScheduled = true;

		// A moved element is disconnected and reconnected in the same task, so it's skipped and keeps its model
		queueMicrotask(() => {
			Sprincul.#unmountScheduled = false;
			const queued = Sprincul.#disconnectedElements;
			Sprincul.#disconnectedElements = new Set();

			const removed = Array.from(queued).filter((element) => !element.isConnected);
			removed.forEach((element) => Sprincul.#pendingElements.delete(element));

			// An element inside another removed one is covered by that one's teardown
			const roots = removed.filter((element) => {
				for (let parent = element.parentElement; parent; parent = parent.parentElement) {
					if (queued.has(parent)) return false;
				}
				return true;
			});

			const models = roots.flatMap((root) => Sprincul.#modelsWithin(root));
			if (models.length === 0) return;

			const teardown = Sprincul.#destroyModels(models, false).finally(() => {
				removed.forEach((element) => {
					if (Sprincul.#elementTeardowns.get(element) === teardown)
						Sprincul.#elementTeardowns.delete(element);
				});
			});
			removed.forEach((element) => Sprincul.#elementTeardowns.set(element, teardown));
		});
	}

	/** Removes and returns the queued custom elements within `root` that are still on the page. */
	static #takePendingElements(root: Node): HTMLElement[] {
		const elements = Array.from(Sprincul.#pendingElements).filter((element) => root.contains(element));
		elements.forEach((element) => Sprincul.#pendingElements.delete(element));
		return elements.filter((element) => element.isConnected);
	}

	static #mountCustomElement(element: HTMLElement): SprinculModelInfo | null {
		// Already mounted: moved, or mounted by hand
		if (getInstance(element)) return null;

		const modelName = Sprincul.#customElements.get(element.localName);
		if (!modelName) return null;

		const teardown = Sprincul.#elementTeardowns.get(element);
		if (teardown) {
			teardown.then(() => {
				if (element.isConnected) Sprincul.#mountCustomElement(element);
			});
			return null;
		}

		try {
			const instance = Sprincul.mount(element, modelName);
			return { name: modelName, element, instance };
		} catch (e) {
			console.error(`[Sprincul] Failed to mount <${element.localName}>:`, e);
			return null;
		}
	}

	/**
	 * Mount every registered `[data-model]` element within `options.root` (default `document.body`), the root included.
	 * Elements already mounted are skipped, so it is safe to call again on content added later.
	 * Nested models mount before the models containing them, so a parent's `afterInit()` finds its children mounted.
	 *
	 * @param {SprinculInitOptions} options
	 *
	 * @return {void}
	 */
	static init(options?: SprinculInitOptions): void {
		if (!Sprincul.#isBrowser) {
			console.warn("[Sprincul] init() called in non-browser environment. Skipping initialization.");
			return;
		}

		const root = options?.root ?? document.body;

		// Custom elements mount themselves; only the ones still queued are mounted here, in the same pass
		const modelElements = Array.from(root.querySelectorAll<HTMLElement>("[data-model]")).filter(
			(element) => !Sprincul.#isCustomElement(element),
		);
		if (root instanceof HTMLElement && root.hasAttribute("data-model") && !Sprincul.#isCustomElement(root)) {
			modelElements.unshift(root);
		}
		if (document.readyState !== "loading") modelElements.push(...Sprincul.#takePendingElements(root));

		modelElements.sort(Sprincul.#childrenFirst);

		const modelInfos: SprinculModelInfo[] = [];

		modelElements.forEach((element) => {
			// A custom element mounts with its model's options and setOption()'s, never a call's, so it behaves
			// the same whether it mounts here or on its own
			if (Sprincul.#isCustomElement(element)) {
				const info = Sprincul.#mountCustomElement(element);
				if (info) modelInfos.push(info);
				return;
			}

			try {
				const info = Sprincul.processModelElement(element as HTMLElement, options?.devMode);
				if (info) modelInfos.push(info);
			} catch (e) {
				console.error(`[Sprincul] Failed to process model element:`, e);
			}
		});

		// Remove page-level cloaks once every model's hooks have been called (not necessarily completed)
		root.querySelectorAll("[data-cloaked]:not([data-model])").forEach((element) => {
			element.removeAttribute("data-cloaked");
		});

		if (options?.onReady) {
			const publicModels = modelInfos.map((info) =>
				Sprincul.#option(
					"devMode",
					Sprincul.#registry.get(info.name),
					Sprincul.#isCustomElement(info.element) ? undefined : options.devMode,
				)
					? info
					: { name: info.name, element: info.element },
			);

			try {
				options.onReady(publicModels);
			} catch (error) {
				console.error("Error in onReady callback:", error);
			}
		}
	}

	/**
	 * Process a single model element
	 * Creates both the user model instance and internal core instance
	 *
	 * @param {HTMLElement} element
	 * @param devModeOption - See `SprinculOptions`; omitted, it falls back like any other option
	 *
	 * @returns The model info, or `null` if the element couldn't be processed
	 */
	static processModelElement(element: HTMLElement, devModeOption?: boolean): SprinculModelInfo | null {
		const modelName = element.dataset.model;
		if (!modelName) {
			console.warn('[Sprincul] Element is missing a "data-model" attribute. Skipping.');
			return null;
		}

		const ModelClass = this.#registry.get(modelName);
		if (!ModelClass) {
			console.warn(`[Sprincul] The model "${modelName}" is not registered. Skipping.`);
			return null;
		}

		const devMode = Sprincul.#option("devMode", ModelClass, devModeOption);

		if (Sprincul.#processedElements.has(element)) {
			if (devMode && Sprincul.#tearingDown(element)) {
				console.warn(
					`[Sprincul] Skipped "${modelName}": the model on this element is still running an async beforeDestroy(). Await unmount() before mounting it again.`,
				);
			}
			return null;
		}
		Sprincul.#processedElements.add(element);

		// Create user's model instance, then link internal core instance
		let model: SprinculModel | undefined;
		let core: SprinculCore;
		let defaults: BoundDefaults;
		try {
			model = new ModelClass(element);
			core = new SprinculCore(model, devMode);
			setCore(model, core);
			Sprincul.#trackModelInstance(modelName, model);

			defaults = core.setupBindings(element);
			Sprincul.#watchDocument(element.ownerDocument);
		} catch (e) {
			// Leave no half-mounted element behind, or it could never be mounted again
			Sprincul.#processedElements.delete(element);
			if (model) {
				deleteCore(model);
				Sprincul.#untrackModelInstance(model);
			}
			throw e;
		}

		// beforeInit is called synchronously; if it returns a Promise, everything below (initial
		// callbacks, listeners, afterInit) waits for it to resolve instead of running immediately.
		let beforeInitResult: unknown;
		try {
			beforeInitResult = Sprincul.#runHook(model, "beforeInit", true, [defaults]);
		} catch (e) {
			console.error('Error in "beforeInit" hook call:', e);
		}

		if (beforeInitResult instanceof Promise) {
			Sprincul.#pendingBeforeInit.add(model);
			beforeInitResult
				.catch((e) => console.error('Error in "beforeInit" hook call:', e))
				.finally(() => {
					Sprincul.#pendingBeforeInit.delete(model);
					// May have been destroyed while pending; don't resurrect a torn-down core.
					if (Sprincul.#destroying.has(model)) return;

					core.runQueuedInitialCallbacks();
					Sprincul.#runAfterInit(model, element);
				});
		} else {
			// beforeInit may have synchronously destroyed this very instance (e.g. called unmount()
			// on itself); don't run afterInit or report it as ready if so.
			if (Sprincul.#destroying.has(model)) return null;

			core.runQueuedInitialCallbacks();
			Sprincul.#runAfterInit(model, element);
		}

		return { name: modelName, element, instance: model };
	}

	/** Calls afterInit and removes the element's cloak once it settles. */
	static #runAfterInit(model: SprinculModel, element: HTMLElement): void {
		let afterHook: unknown;
		try {
			afterHook = Sprincul.#runHook(model, "afterInit", true);
		} catch (e) {
			console.error('Error in "afterInit" hook call:', e);
		}
		Promise.resolve(afterHook)
			.catch((e) => console.error('Error in "afterInit" hook call:', e))
			.finally(() => {
				if (element.hasAttribute("data-cloaked")) {
					element.removeAttribute("data-cloaked");
				}
			});
	}

	/**
	 * Manually mount a model instance on a specific element
	 *
	 * @param element - The HTML element to bind to
	 * @param modelClassOrName - Either a registered model class or the name of a registered model
	 * @param options
	 *
	 * @returns The created model instance
	 */
	static mount<T extends SprinculModel = SprinculModel>(
		element: HTMLElement,
		modelClassOrName: SprinculModelConstructor | string,
		options?: SprinculMountOptions,
	): T {
		let modelName: string;

		if (typeof modelClassOrName === "string") {
			const resolved = Sprincul.#registry.get(modelClassOrName);
			if (!resolved) {
				throw new Error(`Model "${modelClassOrName}" is not registered.`);
			}
			modelName = modelClassOrName;
		} else {
			const existing = Array.from(Sprincul.#registry.entries()).find(([, cls]) => cls === modelClassOrName);

			if (existing) {
				modelName = existing[0];
			} else {
				modelName = modelClassOrName.name || "AnonymousModel";
				let uniqueName = modelName;
				let counter = 1;
				while (Sprincul.#registry.has(uniqueName)) {
					uniqueName = `${modelName}_${counter++}`;
				}
				modelName = uniqueName;
				Sprincul.register(modelName, modelClassOrName);
			}
		}

		const previousModelName = element.dataset.model;
		element.dataset.model = modelName;

		let info: SprinculModelInfo | null;
		try {
			info = Sprincul.processModelElement(element, options?.devMode);
		} catch (e) {
			Sprincul.#restoreModelName(element, previousModelName);
			throw e;
		}

		if (!info || !info.instance) {
			Sprincul.#restoreModelName(element, previousModelName);
			throw new Error(`Failed to mount model on element. It may already be processed. Call unmount() first.`);
		}

		if (options?.onReady) {
			const publicInfo = Sprincul.#option("devMode", Sprincul.#registry.get(modelName), options.devMode)
				? info
				: { name: info.name, element: info.element };

			try {
				options.onReady(publicInfo);
			} catch (error) {
				console.error("Error in onReady callback:", error);
			}
		}

		return info.instance as T;
	}

	/**
	 * Tear down the model on `element` and every model inside it. A parent's `beforeDestroy()` settles
	 * before its nested models are torn down, so it can still reach them.
	 * The reverse of `init({ root })`: `element` doesn't need a model of its own.
	 *
	 * @param element - The element whose models to tear down
	 * @returns A promise that resolves once every `beforeDestroy()` has settled and teardown is complete
	 */
	static unmount(element: HTMLElement): Promise<void>;
	/**
	 * @deprecated An element has only one model, so pass just the element: `unmount(element)`, which also
	 * tears down the models inside it. This form tears down only the model on `element`, if it is named `modelName`.
	 */
	static unmount(element: HTMLElement, modelName: string): Promise<void>;
	static unmount(element: HTMLElement, modelName?: string): Promise<void> {
		if (modelName !== undefined) {
			Sprincul.#warnDeprecated("unmount(element, modelName)", "unmount(element)");
			return Sprincul.#destroyOne(modelName, element);
		}

		return Sprincul.#destroyModels(Sprincul.#modelsWithin(element), true);
	}

	/** The live models on `element` and inside it, in document order. */
	static #modelsWithin(element: HTMLElement): SprinculModel[] {
		const elements = [element, ...Array.from(element.querySelectorAll<HTMLElement>("[data-model]"))];
		return elements.map((candidate) => getInstance(candidate)).filter((model) => model !== undefined);
	}

	/**
	 * Tear down every instance of a model, the same way as `unmount()`.
	 *
	 * @param modelName - The registered model name
	 * @returns A promise that resolves once every `beforeDestroy()` has settled and teardown is complete
	 */
	static destroy(modelName: string): Promise<void>;
	/**
	 * @deprecated Use `unmount(element)` to tear down the model on an element. This form tears down only
	 * the model on `element`, if it is named `modelName`.
	 */
	static destroy(modelName: string, element: HTMLElement): Promise<void>;
	static destroy(modelName: string, element?: HTMLElement): Promise<void> {
		if (element) {
			Sprincul.#warnDeprecated("destroy(modelName, element)", "unmount(element)");
			return Sprincul.#destroyOne(modelName, element);
		}

		return Sprincul.#destroyModels(Array.from(Sprincul.#instancesByName.get(modelName) ?? []), false);
	}

	/** The 0.3.0 single-model teardown behind the deprecated `unmount(el, name)` / `destroy(name, el)`. */
	static #destroyOne(modelName: string, element: HTMLElement): Promise<void> {
		const target = Array.from(Sprincul.#instancesByName.get(modelName) ?? []).find(
			(instance) => instance.$el === element,
		);
		if (target) return Sprincul.#destroyInOrder([target]);

		// Warn only when the element is actually mounted under a different name: destroying an
		// already-destroyed element is a legitimate idempotent call
		if (element.dataset.model && element.dataset.model !== modelName) {
			console.warn(
				`[Sprincul] destroy("${modelName}") found no instance on an element mounted as "${element.dataset.model}".`,
			);
		}
		return Promise.resolve();
	}

	static #warnDeprecated(form: string, replacement: string): void {
		if (Sprincul.#deprecationsWarned.has(form)) return;
		Sprincul.#deprecationsWarned.add(form);
		console.warn(`[Sprincul] ${form} is deprecated and will be removed in a future release; use ${replacement}.`);
	}

	/**
	 * Destroy every live model, the same way as `unmount()`. It also reaches models
	 * whose elements have already left the page.
	 *
	 * @returns A promise that resolves once every `beforeDestroy()` has settled and teardown is complete
	 */
	static destroyAll(): Promise<void> {
		const models: SprinculModel[] = [];
		Sprincul.#instancesByName.forEach((instances) => models.push(...instances));

		return Sprincul.#destroyModels(models, false);
	}

	/**
	 * Order only matters to a `beforeDestroy()` reaching its nested models, so without one among `models`
	 * they're torn down as they come. `inDocumentOrder` skips sorting models that already are.
	 */
	static #destroyModels(models: SprinculModel[], inDocumentOrder: boolean): Promise<void> {
		if (!models.some((model) => typeof model.beforeDestroy === "function")) {
			return Promise.all(models.map((model) => Sprincul.#destroyInstance(model))).then(() => undefined);
		}

		if (!inDocumentOrder) models.sort((a, b) => Sprincul.#documentOrder(a.$el, b.$el));
		return Sprincul.#destroyInOrder(models);
	}

	/**
	 * Destroys `models` (in document order) so that each waits only for its own ancestors' async
	 * `beforeDestroy()`. With no async hooks, everything is torn down before this returns.
	 */
	static #destroyInOrder(models: SprinculModel[]): Promise<void> {
		// Keyed by root element, so each model only walks up its own model ancestors
		const pending = new Map<Element, Promise<void>>();

		models.forEach((model) => {
			const ancestors: Promise<void>[] = [];
			for (
				let ancestor = model.$el.parentElement?.closest("[data-model]");
				ancestor;
				ancestor = ancestor.parentElement?.closest("[data-model]")
			) {
				const teardown = pending.get(ancestor);
				if (teardown) ancestors.push(teardown);
			}

			const teardown =
				ancestors.length === 0
					? Sprincul.#destroyInstance(model)
					: Promise.all(ancestors).then(() => Sprincul.#destroyInstance(model));
			if (teardown) pending.set(model.$el, teardown);
		});

		return Promise.all(pending.values()).then(() => undefined);
	}

	/** True while the model on `element` is waiting on an async beforeDestroy. */
	static #tearingDown(element: HTMLElement): boolean {
		const models: SprinculModel[] = [];
		Sprincul.#instancesByName.forEach((instances) => models.push(...instances));
		return models.some((model) => model.$el === element && Sprincul.#teardowns.has(model));
	}

	/** Sort comparator for children before parents; siblings keep document order. */
	static #childrenFirst(a: Element, b: Element): number {
		if (a.contains(b)) return 1;
		if (b.contains(a)) return -1;
		return Sprincul.#documentOrder(a, b);
	}

	/** Sort comparator for document order (an ancestor comes before its descendants). */
	static #documentOrder(a: Element, b: Element): number {
		return a.compareDocumentPosition(b) & Node.DOCUMENT_POSITION_FOLLOWING ? -1 : 1;
	}

	/** Returns a promise only when beforeDestroy is async; a sync teardown is finished on return. */
	static #destroyInstance(model: SprinculModel): Promise<void> | undefined {
		if (Sprincul.#destroying.has(model)) return Sprincul.#teardowns.get(model);
		Sprincul.#destroying.add(model);
		// Stop handing it out the moment teardown starts
		deleteInstance(model);

		// beforeDestroy is called synchronously; if it returns a Promise, the core stays attached and
		// tracked until it resolves (a remount attempt in the meantime is treated as already processed).
		let beforeDestroyResult: unknown;
		try {
			beforeDestroyResult = Sprincul.#runHook(model, "beforeDestroy", true);
		} catch (e) {
			console.error('Error in "beforeDestroy" hook call:', e);
		}

		if (!(beforeDestroyResult instanceof Promise)) {
			Sprincul.#finishDestroy(model);
			return undefined;
		}

		const teardown = beforeDestroyResult
			.catch((e) => console.error('Error in "beforeDestroy" hook call:', e))
			.then(() => {
				Sprincul.#teardowns.delete(model);
				Sprincul.#finishDestroy(model);
			});
		Sprincul.#teardowns.set(model, teardown);
		return teardown;
	}

	/** Never throws, so one failing model can't stop the rest of a teardown or leave its element unmountable. */
	static #finishDestroy(model: SprinculModel): void {
		try {
			// After beforeDestroy has settled, so it could still rely on what $signal guards
			abortSignal(model);
			getCore(model)?.destroy();
		} catch (e) {
			console.error("[Sprincul] Error while tearing down a model:", e);
		} finally {
			deleteCore(model);
			Sprincul.#processedElements.delete(model.$el);
			Sprincul.#untrackModelInstance(model);
		}
	}

	/** One observer per document, started by its first model, handling the changes inside data-watch elements. */
	static #watchObservers = new WeakMap<Document, MutationObserver>();

	static #watchDocument(document: Document): void {
		const view = document.defaultView;
		if (!view || Sprincul.#watchObservers.has(document)) return;

		const observer = new view.MutationObserver((records) => Sprincul.#applyWatched(records));
		observer.observe(document, { childList: true, subtree: true });
		Sprincul.#watchObservers.set(document, observer);
	}

	/**
	 * Hands each change inside a data-watch element to the model owning that element. Every other change on the page,
	 * and any change that only touches text, is dropped first.
	 */
	static #applyWatched(records: MutationRecord[]): void {
		const changes = new Map<HTMLElement, { added: Set<Element>; removed: Set<Element> }>();
		const isElement = (node: Node): node is Element => node.nodeType === 1;

		for (const record of records) {
			const target = record.target as Element;
			const watched = target.nodeType === 1 ? target.closest<HTMLElement>("[data-watch]") : null;
			if (!watched) continue;

			const added = Array.from(record.addedNodes).filter(isElement);
			const removed = Array.from(record.removedNodes).filter(isElement);
			if (added.length === 0 && removed.length === 0) continue;

			// A change inside a nested model is that model's, unless the nested model watches it itself
			if (closestModelRoot(target) !== closestModelRoot(watched)) continue;

			let change = changes.get(watched);
			if (!change) {
				change = { added: new Set(), removed: new Set() };
				changes.set(watched, change);
			}
			added.forEach((node) => change.added.add(node));
			removed.forEach((node) => change.removed.add(node));
		}

		changes.forEach(({ added, removed }, watched) => {
			const root = closestModelRoot(watched);
			const model = root ? getInstance(root) : undefined;
			const core = model ? getCore(model) : undefined;
			core?.applyWatchedChanges(watched, added, removed);
		});
	}

	static #restoreModelName(element: HTMLElement, previousModelName: string | undefined): void {
		if (previousModelName === undefined) {
			delete element.dataset.model;
			return;
		}
		element.dataset.model = previousModelName;
	}

	static #trackModelInstance(modelName: string, model: SprinculModel): void {
		if (!Sprincul.#instancesByName.has(modelName)) {
			Sprincul.#instancesByName.set(modelName, new Set());
		}

		Sprincul.#instancesByName.get(modelName)!.add(model);
		Sprincul.#modelNames.set(model, modelName);
		setInstance(model.$el, model);
	}

	static #untrackModelInstance(model: SprinculModel): void {
		deleteInstance(model);

		const modelName = Sprincul.#modelNames.get(model);
		if (!modelName) return;

		const instances = Sprincul.#instancesByName.get(modelName);
		if (!instances) return;

		instances.delete(model);
		if (instances.size === 0) {
			Sprincul.#instancesByName.delete(modelName);
		}
	}

	static #runHook(
		instance: SprinculModel,
		methodName: string,
		sync: boolean = false,
		args: unknown[] = [],
	): unknown | Promise<unknown> | undefined {
		const hook = Reflect.get(instance, methodName);
		if (typeof hook !== "function") return undefined;
		if (sync) return hook.call(instance, ...args);

		return Promise.resolve().then(() => hook.call(instance, ...args));
	}
}
